/**
 * Icon helper. Two kinds share one API:
 *
 * - SVG silhouettes in public/assets/ui/icons/*.svg, drawn as a CSS mask so
 *   they inherit `color` (menus, panels, alerts).
 * - Coloured pixel-art frames from the icon sheets (icons.png, icons@2x.png,
 *   generated by scripts/ui/gen_icons.py) for the in-game HUD: resources,
 *   commands, buildings, units, stats, tech. These get the `is-px` class and
 *   their frame as CSS variables; styles/components.css picks the sheet for
 *   the current texel size and sizes the element at one sheet pixel per half
 *   texel unless a context overrides `--ix` (texels per sheet pixel).
 */

import type { IconName, SvgIconName } from './icon-names';
import { RASTER_ICONS, RASTER_SHEET, type RasterIconName } from './raster-icons';

export const ICON_BASE = '/assets/ui/icons/';

const RASTER_VARS = ['--iw', '--ih', '--ibs', '--ibp'] as const;

export function isRasterIcon(name: string): name is RasterIconName {
  return Object.prototype.hasOwnProperty.call(RASTER_ICONS, name);
}

export function iconUrl(name: SvgIconName): string {
  return `${ICON_BASE}${name}.svg`;
}

function pct(n: number): string {
  return `${Number(n.toFixed(4))}%`;
}

/**
 * Frame of a sheet icon as CSS custom properties. Size and position are in
 * percent so the frame fits any element box with the frame's aspect ratio.
 */
export function rasterVars(name: RasterIconName): Record<(typeof RASTER_VARS)[number], string> {
  const [x, y, w, h]: readonly number[] = RASTER_ICONS[name];
  const sw: number = RASTER_SHEET.w;
  const sh: number = RASTER_SHEET.h;
  return {
    '--iw': String(w),
    '--ih': String(h),
    '--ibs': `${pct((sw / w) * 100)} ${pct((sh / h) * 100)}`,
    '--ibp': `${sw === w ? '0%' : pct((x / (sw - w)) * 100)} ${sh === h ? '0%' : pct((y / (sh - h)) * 100)}`,
  };
}

/** Create a decorative icon element. Pass `label` to expose it to assistive tech. */
export function icon(name: IconName, className = '', label?: string): HTMLSpanElement {
  const el = document.createElement('span');
  el.className = className ? `icon ${className}` : 'icon';
  setIcon(el, name);
  if (label) {
    el.setAttribute('role', 'img');
    el.setAttribute('aria-label', label);
  } else {
    el.setAttribute('aria-hidden', 'true');
  }
  return el;
}

/** Swap the glyph of an existing icon element (no-op if unchanged). */
export function setIcon(el: HTMLElement, name: IconName): void {
  if (el.dataset.icon === name) return;
  el.dataset.icon = name;
  if (isRasterIcon(name)) {
    el.classList.add('is-px');
    el.style.removeProperty('--icon');
    for (const [k, v] of Object.entries(rasterVars(name))) el.style.setProperty(k, v);
  } else {
    el.classList.remove('is-px');
    for (const k of RASTER_VARS) el.style.removeProperty(k);
    el.style.setProperty('--icon', `url("${iconUrl(name)}")`);
  }
}

/** Same as icon() but as an HTML string, for template-built rows. */
export function iconHtml(name: IconName, className = ''): string {
  if (isRasterIcon(name)) {
    const style = Object.entries(rasterVars(name))
      .map(([k, v]) => `${k}:${v}`)
      .join(';');
    return `<span class="icon is-px${className ? ` ${className}` : ''}" aria-hidden="true" data-icon="${name}" style="${style}"></span>`;
  }
  return `<span class="icon${className ? ` ${className}` : ''}" aria-hidden="true" data-icon="${name}" style="--icon:url('${iconUrl(name)}')"></span>`;
}
